int Mark(string label, int value) { Print(label); return value; }
class Person {
    public int First = Mark("field", 1);
    public int Count { get; private set; } = Mark("property", 2);
    public string Name { get; }
    public bool Flag { get; set; }
    public Person(string name) { Print("body"); Name = name; Count += 3; }
    public void Add() { Count++; }
    public string Label => Name + ":" + Count;
}
void Main() { var p = new Person("Ada"); var alias = p; alias.Add(); Print(p.Label); Print(p.Flag); p.Flag = true; Print(alias.Flag); }
